WITH Src AS (SELECT *, UPPER(status) AS status_upper FROM subscriptions WHERE status = 'EXPIRED'), subscriptions_stats AS (SELECT MONTH(start_date) AS start_month, AVG(monthly_fee) AS avg_monthly_fee, SUM(CASE WHEN plan = 'enterprise' THEN 1 ELSE 0 END) AS enterprise_count FROM Src GROUP BY MONTH(start_date)) SELECT start_month, avg_monthly_fee, enterprise_count FROM subscriptions_stats ORDER BY 3 DESC, start_month LIMIT 20;
